import {createHash} from 'node:crypto';

// These definitions are generated by the fixed structured SQL tools. Output
// aliases, keyword case and whitespace cannot turn a query into independent
// evidence. This is a conservative identity check, not a SQL semantic prover.
export function queryEvidenceIdentity(data){
 const q=data?.queryDefinition;if(!data?.queryHash||!q||typeof q.sql!=='string'||!Array.isArray(q.params))return null;
 const tokens=q.sql.match(/`(?:``|[^`])*`|'(?:''|\\.|[^'\\])*'|"(?:""|\\.|[^"\\])*"|[a-z_][a-z0-9_]*|[^\s]/gi)??[];
 const normalized=[];
 for(let i=0;i<tokens.length;i++){
  const token=tokens[i];
  if(/^as$/i.test(token)&&/^(?:`(?:``|[^`])*`|[a-z_][a-z0-9_]*)$/i.test(tokens[i+1]??'')){i++;continue;}
  normalized.push(/^[`'"]/.test(token)?token:token.toLowerCase());
 }
 const sql=normalized.join(' ');
 return createHash('sha256').update(JSON.stringify([sql,q.params.map(v=>String(v))])).digest('hex');
}
